 3	use Modules\AI\Domain\Decision\DefenseNeedEvaluator;
 4	use Modules\AI\Tests\Support\Situation;
 5	use OGame\Factories\PlanetServiceFactory;
 6	use OGame\Models\Planet;
 7	use Tests\IsolatedAccountTestCase;
 8	
 9	require_once __DIR__ . '/../Support/Situation.php';
10	
11	uses(IsolatedAccountTestCase::class);
12	
13	// The live shape of invariant:NAKED_BESIDE_WALLED that survives a walled homeworld: a colony that
14	// holds a walled sibling and almost nothing of its own. A player ferries resources to a colony that
15	// cannot pay for its own next step, so the colony is not left naked beside the account's wall.
16	// The bound: a wall already standing on a planet must not read as naked, or the account would keep
17	// paying for the homeworld's wall instead of reaching the colony beside it.
18	test('a bare colony beside a walled homeworld takes a wall of its own', function (): void {
19	    $situation = Situation::of($this)
20	        ->resources(50_000_000, 50_000_000, 50_000_000)
21	        ->level('robot_factory', 2)
22	        ->level('shipyard', 4)
23	        ->defence('rocket_launcher', 20)
24	        ->colony()
25	        ->sessions(4, 60);
26	
27	    $owned = Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)->pluck('id');
28	
29	    foreach ($owned as $planetId) {
30	        $planet = app(PlanetServiceFactory::class)->make((int) $planetId, true);
31	        $planet->updateResources(false);
32	
33	        expect(app(DefenseNeedEvaluator::class)->standingUnits($planet))->toBeGreaterThan(
34	            0,
35	            'expected a wall on planet ' . $planetId . '; ' . $situation->account()
36	        );
37	    }
38	});

 1	<?php
 2	
 3	use Illuminate\Support\Facades\DB;
 4	use Modules\AI\Actions\ReviewAiAllianceApplicationsAction;
 5	use Modules\AI\Enums\AiArchetype;
 6	use Modules\AI\Enums\AiSkillBand;
 7	use Modules\AI\Models\AiProfile;
 8	use OGame\Models\AllianceApplication;
 9	use OGame\Models\Highscore;
10	use OGame\Models\User;
11	use OGame\Services\AllianceService;
12	use Tests\IsolatedAccountTestCase;
13	
14	uses(IsolatedAccountTestCase::class);
15	
16	// SIM-001's situation (scripts/cohort-scenario.php `alliance-application`): an application row (status
17	// pending) waits on an alliance an AI account leads. A leader reads it and decides; it does not
18	// sit pending past the age floor.
19	test('a pending application to an AI-led alliance is decided on the leader\'s next pass', function (): void {
20	    AiProfile::create([
21	        'player_id' => $this->currentUserId,
22	        'archetype' => AiArchetype::Casual,
23	        'skill_band' => AiSkillBand::Standard,
24	        'random_seed' => 18_000 + $this->currentUserId,
25	        'enabled' => true,
26	    ]);
27	    $alliance = app(AllianceService::class)->createAlliance($this->currentUserId, 'SITU', 'Situation');
28	    $applicant = User::factory()->create();
29	    Highscore::unguarded(fn () => Highscore::updateOrCreate(
30	        ['player_id' => $applicant->id],
31	        ['general' => 1000, 'general_rank' => 1, 'economy' => 1000, 'research' => 1000],
32	    ));
33	
34	    // The row the live situation plants: alliance_id, user_id, application_message, status 0.
35	    $id = DB::table('alliance_applications')->insertGetId([
36	        'alliance_id' => $alliance->id,
37	        'user_id' => $applicant->id,
38	        'application_message' => 'Active player looking for a home.',
39	        'status' => AllianceApplication::STATUS_PENDING,
40	        'created_at' => now()->subMinutes(30),
41	        'updated_at' => now()->subMinutes(30),
42	    ]);
43	
44	    expect(app(ReviewAiAllianceApplicationsAction::class)->handle())->toBe(1)
45	        ->and(AllianceApplication::query()->whereKey($id)->value('status'))->not->toBe(AllianceApplication::STATUS_PENDING);
46	});

