test('a walled homeworld takes no further wall while its colony is still bare', function (): void {
    povertyProfile($this->currentUserId);

    $home = $this->planetService;
    povertyWalledHome($home);

    // A colony that mines nothing and whose yard cannot build a wall yet: the naked planet the cohort
    // read found beside the account's wall. Nothing here can be served, so the walled homeworld is the
    // only planet that could take the order -- and it must not.
    povertyBareColony($this->secondPlanetService);

    $plan = app(QueueableUnitPlanner::class)->plan($this->currentUserId);

    expect($plan?->reason ?? '')->not->toContain('role:defense')
        ->and($plan?->planetId)->not->toBe($home->getPlanetId());
});

// The bound on the other side: the same account, with the bare colony able to pay for and build its own
// wall, spends the order on the colony and still leaves the sibling that already stands a wall alone.
test('the bare colony beside the walled homeworld takes the wall once it can pay for it', function (): void {
    povertyProfile($this->currentUserId);

    $home = $this->planetService;
    povertyWalledHome($home);

    $colony = povertyBareColony($this->secondPlanetService);
    $colony->setObjectLevel(ObjectService::getObjectByMachineName('robot_factory')->id, 2, true);
    $colony->setObjectLevel(ObjectService::getObjectByMachineName('shipyard')->id, 4, true);
    $colony->updateResourceProductionStats();
    $colony->updateResourceStorageStats();
    $colony->addResources(new Resources(50_000_000, 50_000_000, 50_000_000));

    $plan = app(QueueableUnitPlanner::class)->plan($this->currentUserId);

    expect($plan)->not->toBeNull()
        ->and($plan->reason)->toContain('role:defense:standing')
        ->and($plan->planetId)->toBe($colony->getPlanetId());
});

function povertyProfile(int $playerId): AiProfile
{
    return AiProfile::create([
        'player_id' => $playerId,
        'archetype' => AiArchetype::Miner,
        'skill_band' => AiSkillBand::Standard,
        'random_seed' => 51_000 + $playerId,
        'enabled' => true,
    ]);
}

/**
 * A homeworld that already stands a wall and whose economy and fleet are worth far more than it: the
 * exposure the evaluator sizes from (PERS-004) is what makes it ask for further wall, so withholding the
 * order is the rule under test rather than a need the planet never had.
 */
function povertyWalledHome(PlanetService $home): void
{
    foreach (['robot_factory' => 2, 'shipyard' => 4, 'solar_plant' => 30, 'metal_mine' => 20, 'crystal_mine' => 18, 'deuterium_synthesizer' => 12] as $machineName => $level) {
        $home->setObjectLevel(ObjectService::getObjectByMachineName($machineName)->id, $level, true);
    }

    $home->updateResourceProductionStats();
    $home->updateResourceStorageStats();
    $home->addUnit('rocket_launcher', 2);
    povertyOpeningFleet($home);
    $home->addResources(new Resources(50_000_000, 50_000_000, 50_000_000));
}

/**
 * A colony that mines nothing, holds no defence and whose yard cannot build any: the planet the cohort
 * read found naked beside a walled sibling. Its own yard and stock decide whether it can be served, so a
 * story plants what it means it to have afterwards.
 */
function povertyBareColony(?PlanetService $colony): PlanetService
{
    $colony = $colony ?? throw new LogicException('the account must own a second planet for this story.');

    foreach (['robot_factory', 'shipyard', 'metal_mine', 'crystal_mine', 'deuterium_synthesizer'] as $machineName) {
        $colony->setObjectLevel(ObjectService::getObjectByMachineName($machineName)->id, 0, true);
    }

    $colony->updateResourceProductionStats();
    $colony->updateResourceStorageStats();

    return $colony;
}

/** A planet whose opening roles are satisfied, so the wall is what the planner is left with. */
function povertyOpeningFleet(PlanetService $planet): void
{
    $planet->addUnit('small_cargo', 1);
    $planet->addUnit('colony_ship', 1);
    $planet->addUnit('espionage_probe', 1);
}"}

